package org.cbhs.bank.testers;

import org.cbhs.bank.model.Account;
import org.cbhs.bank.model.Bank;

import java.io.IOException;

/**
 * Run this class to check Bank. Students do not edit this file.
 * Run from the project folder so data/accounts.txt can be found.
 */
public class BankTester {
    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args) {
        testAddFindAndNumbers();
        testSearch();
        testStats();
        testTransfer();
        testInterest();
        testLoadFromFile();
        printSummary();
    }

    private static void testAddFindAndNumbers() {
        Bank bank = new Bank();
        check("empty bank next number is 1001", bank.nextAccountNumber() == 1001);
        check("add first account", bank.addAccount(new Account(1001, "Maya Patel", "checking", 100)));
        check("find 1001", bank.findAccount(1001) != null);
        check("missing account is null", bank.findAccount(9999) == null);
        check("duplicate number rejected", !bank.addAccount(new Account(1001, "Other", "savings", 1)));
        check("count is 1", bank.countAccounts() == 1);
        check("next number after 1001 is 1002", bank.nextAccountNumber() == 1002);
    }

    private static void testSearch() {
        Bank bank = new Bank();
        bank.addAccount(new Account(1001, "Robotics Club", "checking", 250));
        bank.addAccount(new Account(1002, "Robotics Club", "savings", 900));
        bank.addAccount(new Account(1003, "Maya Patel", "checking", 157.50));
        check("search Rob finds 2", bank.findAccountsByName("Rob").size() == 2);
        check("search rob finds 0 (case-sensitive)", bank.findAccountsByName("rob").size() == 0);
        check("search Maya finds 1", bank.findAccountsByName("Maya").size() == 1);
    }

    private static void testStats() {
        Bank bank = new Bank();
        check("empty total is 0", almostEqual(bank.totalAssets(), 0));
        check("empty average is 0", almostEqual(bank.averageBalance(), 0));
        check("empty largest is null", bank.largestAccount() == null);
        bank.addAccount(new Account(1001, "A", "checking", 100));
        bank.addAccount(new Account(1002, "B", "savings", 300));
        check("total assets", almostEqual(bank.totalAssets(), 400));
        check("average balance", almostEqual(bank.averageBalance(), 200));
        check("largest is 1002", bank.largestAccount().getAccountNumber() == 1002);
    }

    private static void testTransfer() {
        Bank bank = new Bank();
        bank.addAccount(new Account(1001, "A", "checking", 100));
        bank.addAccount(new Account(1002, "B", "checking", 50));
        check("transfer 25 succeeds", bank.transfer(1001, 1002, 25, "Dues", "2026-08-13"));
        check("from balance after transfer", almostEqual(bank.findAccount(1001).getBalance(), 75));
        check("to balance after transfer", almostEqual(bank.findAccount(1002).getBalance(), 75));
        check("same account transfer fails", !bank.transfer(1001, 1001, 10, "Nope", "2026-08-13"));
        check("overdraw transfer fails", !bank.transfer(1001, 1002, 1000, "Nope", "2026-08-13"));
        check("from unchanged after failed transfer", almostEqual(bank.findAccount(1001).getBalance(), 75));
    }

    private static void testInterest() {
        Bank bank = new Bank();
        bank.addAccount(new Account(1001, "A", "checking", 100));
        bank.addAccount(new Account(1002, "B", "savings", 900));
        int updated = bank.applyInterest("2026-08-13");
        check("interest updates 1 savings account", updated == 1);
        check("checking unchanged", almostEqual(bank.findAccount(1001).getBalance(), 100));
        check("savings grew 5%", almostEqual(bank.findAccount(1002).getBalance(), 945));
    }

    private static void testLoadFromFile() {
        Bank bank = new Bank();
        bank.addAccount(new Account(1, "Temp", "checking", 1));
        try {
            bank.loadFromFile("data/accounts.txt");
        } catch (IOException e) {
            check("loadFromFile ran without error", false);
            return;
        }
        check("reload replaces old accounts", bank.findAccount(1) == null);
        check("seed has 6 accounts", bank.countAccounts() == 6);
        check("Robotics Club checking is 1001", bank.findAccount(1001) != null
                && bank.findAccount(1001).getOwnerName().equals("Robotics Club"));
    }

    private static void check(String name, boolean ok) {
        if (ok) {
            passed++;
            System.out.println(name + " ... PASS");
        } else {
            failed++;
            System.out.println(name + " ... FAIL");
        }
    }

    private static boolean almostEqual(double a, double b) {
        return Math.abs(a - b) < 0.001;
    }

    private static void printSummary() {
        System.out.println();
        System.out.println("Passed: " + passed + "  Failed: " + failed);
        if (failed == 0) {
            System.out.println("BankTester: all tests passed.");
        } else {
            System.out.println("BankTester: some tests failed.");
        }
    }
}
